/* MH4U's save file cipher on the console: core/save/crypt.py in C. A `userN` file is
 * Blowfish (ECB, each half of a block a little-endian word, with the key fixed in the game) over an XOR stream seeded
 * from the header's high half, over the plain file whose u32 at 4 is the sum of its bytes from 8. A card file is the
 * same with Blowfish from byte HF_SAVECRYPT_CARD_BLOWFISH_FROM. Portable C99; savecrypt_tables.h is generated by
 * tools/build/gen_launcher_save.py. */
#ifndef HF_SAVECRYPT_H
#define HF_SAVECRYPT_H

#include <stdint.h>

#include "savecrypt_tables.h"

typedef struct {
    uint32_t p[18];
    uint32_t s[4][256];
} HfBlowfish;

/* The game's key scheduled (about 4 KB: keep one, on the heap). */
void hf_blowfish_init(HfBlowfish *bf);

/* The sum of the bytes from 8 (the u32 a plain file keeps at 4). */
uint32_t hf_save_checksum(const uint8_t *plain, uint32_t size);

/* `data` (an encrypted file of `size` bytes) decrypted in place, as crypt.decrypt: 0 when its checksum matches (the
 * game loads it), -1 when it does not (the game calls the file corrupt), -2 for a size the cipher cannot take (Blowfish
 * needs whole 8-byte blocks after `blowfish_from`, the header 8 bytes). `seed` (may be NULL) gets the XOR seed. */
int hf_save_decrypt(const HfBlowfish *bf, uint8_t *data, uint32_t size, uint32_t blowfish_from, uint32_t *seed);
/* A plain file encrypted in place with `seed` (its low 16 bits), its checksum computed first, as crypt.encrypt. 0, or
 * -2 for a size the cipher cannot take (nothing changed). */
int hf_save_encrypt(const HfBlowfish *bf, uint8_t *data, uint32_t size, uint32_t blowfish_from, uint32_t seed);

#endif
